$x_{2}=1-\left( \dfrac{13}{14} \right)= \dfrac{1}{14}$\\
Vậy $x_{1}\cdot x_{2}= {\dfrac{13}{196}}$\\
$\dfrac{1}{x_{1}}+ \dfrac{1}{x_{2}}= \dfrac{x_{1}+x_{2}}{x_{1}x_{2}}= \dfrac{196}{13}$
}\end{ex}

\begin{ex}%[9D6V3-5]
Biết rằng phương trình bậc hai ${3x^{2}-3x+m=0}$ có một nghiệm là ${\dfrac{1}{2} + \dfrac{\sqrt{10}}{5}} $. Tính tổng nghịch đảo của hai nghiệm.
\loigiai{
Phương trình bậc hai ${3x^{2}-3x+m=0}$ có một nghiệm là ${\dfrac{1}{2} + \dfrac{\sqrt{10}}{5}} $ nên có nghiệm thứ hai là $x_{2}$\\
Ta có $x_{2}+\dfrac{1}{2} + \dfrac{\sqrt{10}}{5}=1 $\\
$x_{2}=1-\left( \dfrac{1}{2} + \dfrac{\sqrt{10}}{5} \right)= \dfrac{1}{2} - \dfrac{\sqrt{10}}{5}$\\
Vậy $x_{1}\cdot x_{2}= {- \dfrac{3}{20}}$\\
$\dfrac{1}{x_{1}}+ \dfrac{1}{x_{2}}= \dfrac{x_{1}+x_{2}}{x_{1}x_{2}}= - \dfrac{20}{3}$
}\end{ex}

\begin{ex}%[9D6V3-5]
Biết rằng phương trình bậc hai ${-4x^{2}+x+m=0}$ có một nghiệm là ${\dfrac{1}{8} + \dfrac{\sqrt{7}}{3}} $. Tính tổng nghịch đảo của hai nghiệm.
\loigiai{
Phương trình bậc hai ${-4x^{2}+x+m=0}$ có một nghiệm là ${\dfrac{1}{8} + \dfrac{\sqrt{7}}{3}} $ nên có nghiệm thứ hai là $x_{2}$\\
Ta có $x_{2}+\dfrac{1}{8} + \dfrac{\sqrt{7}}{3}=\dfrac{1}{4} $\\
$x_{2}=\dfrac{1}{4}-\left( \dfrac{1}{8} + \dfrac{\sqrt{7}}{3} \right)= \dfrac{1}{8} - \dfrac{\sqrt{7}}{3}$\\
Vậy $x_{1}\cdot x_{2}= {- \dfrac{439}{576}}$\\
$\dfrac{1}{x_{1}}+ \dfrac{1}{x_{2}}= \dfrac{x_{1}+x_{2}}{x_{1}x_{2}}= - \dfrac{144}{439}$
}\end{ex}

\begin{ex}%[9D6V3-5]
Biết rằng phương trình bậc hai ${-4x^{2}-2x+m=0}$ có một nghiệm là ${- \dfrac{1}{4} + \dfrac{\sqrt{2}}{3}} $. Tính tổng nghịch đảo của hai nghiệm.
\loigiai{
Phương trình bậc hai ${-4x^{2}-2x+m=0}$ có một nghiệm là ${- \dfrac{1}{4} + \dfrac{\sqrt{2}}{3}} $ nên có nghiệm thứ hai là $x_{2}$\\
Ta có $x_{2}- \dfrac{1}{4} + \dfrac{\sqrt{2}}{3}=- \dfrac{1}{2} $\\
$x_{2}=- \dfrac{1}{2}-\left( - \dfrac{1}{4} + \dfrac{\sqrt{2}}{3} \right)= - \dfrac{\sqrt{2}}{3} - \dfrac{1}{4}$\\
Vậy $x_{1}\cdot x_{2}= {- \dfrac{23}{144}}$\\
$\dfrac{1}{x_{1}}+ \dfrac{1}{x_{2}}= \dfrac{x_{1}+x_{2}}{x_{1}x_{2}}= \dfrac{72}{23}$
}\end{ex}
